import React, { useState, useRef, useEffect } from "react";
import { db, storage, auth } from "../utilis/Firebase";
import { signOut } from "firebase/auth";
import { collection, addDoc, Timestamp, doc, getDoc } from "firebase/firestore";
import { ref, uploadBytesResumable, getDownloadURL } from "firebase/storage";
import MediaFeed from "../feed/MediaFeed";
import imageCompression from "browser-image-compression";
import { useNavigate } from "react-router-dom";
import "./MediaPost.css";
import globe from './regulareEarth.png'

const MediaPost = () => {
  const [text, setText] = useState("");
  const [media, setMedia] = useState([]);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef(null);
  const navigate = useNavigate();
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");

  useEffect(() => {
    const fetchUserData = async () => {
      if (auth.currentUser) {
        const userDoc = await getDoc(doc(db, "users", auth.currentUser.uid));
        if (userDoc.exists()) {
          setFirstName(userDoc.data().firstName || "");
          setLastName(userDoc.data().lastName || "");
        }
      }
    };

    fetchUserData();
  }, []);

  const handleLogout = async () => {
    try {
      await signOut(auth);
      navigate("/");
    } catch (error) {
      console.error("Error logging out:", error);
    }
  };

  const handleTextChange = (e) => {
    setText(e.target.value);
  };

  const handleMediaChange = (e) => {
    setMedia([...e.target.files]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (text.trim() || media.length > 0) {
      setUploading(true);
      const compressedFiles = await compressImages(media);
      const mediaUrls = await uploadMediaFiles(compressedFiles);
      await savePostToFirestore(text.trim(), mediaUrls);
      setText("");
      setMedia([]);
      fileInputRef.current.value = "";
      setUploading(false);
    }
  };

  const compressImages = async (files) => {
    const options = {
      maxSizeMB: 1,
      maxWidthOrHeight: 800,
      useWebWorker: true,
    };

    const compressedFilesPromises = files.map(async (file) => {
      try {
        const compressedFile = await imageCompression(file, options);
        return compressedFile;
      } catch (error) {
        console.error("Error while compressing the image:", error);
        return file;
      }
    });

    return Promise.all(compressedFilesPromises);
  };

  const uploadMediaFiles = async (files) => {
    const promises = files.map((file) => {
      const storageRef = ref(storage, `mediaposts/${Date.now()}-${file.name}`);
      const uploadTask = uploadBytesResumable(storageRef, file);

      return new Promise((resolve, reject) => {
        uploadTask.on(
          "state_changed",
          null,
          (error) => reject(error),
          async () => {
            const downloadUrl = await getDownloadURL(uploadTask.snapshot.ref);
            resolve(downloadUrl);
          }
        );
      });
    });

    return Promise.all(promises);
  };

  const savePostToFirestore = async (text, mediaUrls) => {
    const postRef = collection(db, "mediaposts");
    await addDoc(postRef, {
      text,
      mediaUrls,
      createdAt: Timestamp.now(),
    });
  };

  return (
    <div className="media-post-container">
      <div className="header-container">
        <div>
          {firstName && lastName && (
            <p className="welcome-message">
              Welcome, {firstName} {lastName}!
            </p>
          )}
        </div>
        <button className="logout-btn" onClick={handleLogout}>
          Logout
        </button>
      </div>
      <h1 className="daily-bugle-title">
        <span className="skew-text">FRESH</span>
        <img src={globe} alt="Globe" className="globe-image" />
        <span className="skew-text">PAPER</span>
      </h1>

      <form className="media-post-form" onSubmit={handleSubmit}>
        <textarea
          placeholder="Write something..."
          value={text}
          onChange={handleTextChange}
        />
        <input
          type="file"
          onChange={handleMediaChange}
          accept="image/*,video/*"
          multiple
          ref={fileInputRef}
        />
        <button type="submit" disabled={uploading}>
          {uploading ? "Posting..." : "Post"}
        </button>
      </form>

      <MediaFeed />
    </div>
  );
};

export default MediaPost;